==['Romance'] assert api.post('/query/resolve',json=body).status_code==409 and collection().find_one({'_id':sid})==resolved turn('deep learning instead','EXECUTABLE');p=collection().find_one({'_id':sid});assert p['current_plan']['subjects']==['Deep learning'] clear(sid,ACTOR,lid);assert collection().find_one({'_id':sid}) is None turn('books about planets','EXECUTABLE');before=deepcopy(collection().find_one({'_id':sid})) from fastapi import HTTPException with pytest.raises(HTTPException):tenant_search(worker,lid,{'sub':'2','sid':'another-login'},'books about stars',session_id=sid) assert collection().find_one({'_id':sid})==before database.institution_memberships.update_one({'library_id':lid,'user_id':2},{'$set':{'status':'REMOVED'}}) with pytest.raises(HTTPException):tenant_search(worker,lid,ACTOR,'books about planets',session_id=sid) assert collection().find_one({'_id':sid}) is None path=Path(__file__).resolve().parents[2]/'reports'/os.getenv('LUMINAR_SEARCH_SESSION_REPORT','search_v2c_c_session_sequences.json');data=json.loads(path.read_text()) if path.exists() else [] > data.append({'case_id':'sequence-rating-'+str(minimum),'database':database.name,'turns':observed,'forged_unchanged':True,'resolution_single_commit':True,'duplicate_unchanged':True,'cross_sid_unchanged':True,'clear_verified':True,'revocation_invalidated':True,'corruption_events':0}) ^^^^^^^^^^^ E AttributeError: 'dict' object has no attribute 'append'
